export const MudraCoin: React.FC<MudraCoinProps> = ({
  size = 20,
  isPulsing = false,
  isSpinning = false,
  style,
  className,
  testID = 'mudra-coin',
}) => {
  const rawId = useId();
  // Sanitize id for valid SVG identifiers
  const uid = `mudra_${rawId.replace(/[^a-zA-Z0-9_-]/g, '')}`;

  const paint0Id = `${uid}_p0`;
  const paint1Id = `${uid}_p1`;
  const paint2Id = `${uid}_p2`;
  const clip0Id = `${uid}_c0`;
  const clip1Id = `${uid}_c1`;
  const clip2Id = `${uid}_c2`;

  const containerStyle = [
    {
      width: size,
      height: size,
      display: 'inline-flex',
      alignItems: 'center',
      justifyContent: 'center',
      flexShrink: 0,
      ...(isPulsing
        ? {
            filter: 'drop-shadow(0 0 6px rgba(212, 175, 55, 0.75))',
            transform: [{ scale: 1.05 }],
            transition: 'all 0.3s ease',
          }
        : {}),
      ...(isSpinning
        ? {
            animation: 'mudraSpin 3s linear infinite',
          }
        : {}),
    },
    style,
  ];

  // In Web environments (DOM / RNW), render the high-fidelity SVG with exact Figma conic sheen
  if (Platform.OS === 'web') {
    return (
      <div
        data-testid={testID}
        className={className}
        style={{
          width: size,
          height: size,
          display: 'inline-flex',
          alignItems: 'center',
          justifyContent: 'center',
          flexShrink: 0,
          position: 'relative',
          verticalAlign: 'middle',
          lineHeight: 0,
          boxSizing: 'border-box',
          ...(isPulsing ? { filter: 'drop-shadow(0 0 6px rgba(212, 175, 55, 0.75))' } : {}),
          ...style,
        }}
      >
        <svg
          width={size}
          height={size}
          viewBox="0 0 150 150"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
          style={{ width: '100%', height: '100%', display: 'block' }}
        >
          {/* Base Diamond Gradient Coin Rim */}
          <g clipPath={`url(#${clip0Id})`}>
            <g transform="matrix(0.111746 -0.101947 0.101947 0.111746 38.2538 106.281)">
              <rect x="0" y="0" width="1028.65" height="720.759" fill={`url(#${paint0Id})`} opacity="1" />
              <rect x="0" y="0" width="1028.65" height="720.759" transform="scale(1 -1)" fill={`url(#${paint0Id})`} opacity="1" />
              <rect x="0" y="0" width="1028.65" height="720.759" transform="scale(-1 1)" fill={`url(#${paint0Id})`} opacity="1" />
              <rect x="0" y="0" width="1028.65" height="720.759" transform="scale(-1)" fill={`url(#${paint0Id})`} opacity="1" />
            </g>
          </g>

          {/* Inner Coin Surface with Radiant Conic Sheen */}
          <g clipPath={`url(#${clip1Id})`}>
            <g transform="matrix(-0.0263819 0.0084799 -0.0084799 -0.0263819 79.8995 143.216)">
              <foreignObject x="-5847.94" y="-5847.94" width="11695.9" height="11695.9">
                <div
                  style={{
                    background:
                      'conic-gradient(from 90deg, rgba(216, 173, 42, 1) 0deg, rgba(255, 255, 255, 1) 0.64deg, rgba(216, 173, 42, 1) 360deg)',
                    height: '100%',
                    width: '100%',
                    opacity: 1,
                  }}
                />
              </foreignObject>
            </g>
          </g>

          {/* Center Mudra Knot Emblem with Diamond Gold Lustre */}
          <g clipPath={`url(#${clip2Id})`}>
            <g transform="matrix(0.0482412 0.00810302 -0.00803365 0.0478282 67.0854 87.4372)">
              <rect x="0" y="0" width="1906.99" height="2084.94" fill={`url(#${paint2Id})`} opacity="1" />
              <rect x="0" y="0" width="1906.99" height="2084.94" transform="scale(1 -1)" fill={`url(#${paint2Id})`} opacity="1" />
              <rect x="0" y="0" width="1906.99" height="2084.94" transform="scale(-1 1)" fill={`url(#${paint2Id})`} opacity="1" />
              <rect x="0" y="0" width="1906.99" height="2084.94" transform="scale(-1)" fill={`url(#${paint2Id})`} opacity="1" />
            </g>
          </g>

          <defs>
            <clipPath id={clip0Id}>
              <path d={OUTER_BASE_PATH} />
            </clipPath>
            <clipPath id={clip1Id}>
              <path d={INNER_CIRCLE_PATH} />
            </clipPath>
            <clipPath id={clip2Id}>
              <path d={EMBLEM_PATH} fillRule="evenodd" clipRule="evenodd" />
            </clipPath>

            <linearGradient id={paint0Id} x1="0" y1="0" x2="500" y2="500" gradientUnits="userSpaceOnUse">
              <stop offset="0.0988339" stopColor="#ECD289" />
              <stop offset="0.735577" stopColor="#A08049" />
            </linearGradient>

            <linearGradient id={paint2Id} x1="0" y1="0" x2="500" y2="500" gradientUnits="userSpaceOnUse">
              <stop stopColor="#1E180E" />
              <stop offset="1" stopColor="#F2BA0F" />
            </linearGradient>
          </defs>
        </svg>
      </div>
    );
  }

  // Native Mobile (Android/iOS) implementation using react-native-svg
  return (
    <Svg
      testID={testID}
      width={size}
      height={size}
      viewBox="0 0 150 150"
      style={containerStyle}
    >
      <Defs>
        <ClipPath id={clip0Id}>
          <Path d={OUTER_BASE_PATH} />
        </ClipPath>
        <ClipPath id={clip1Id}>
          <Path d={INNER_CIRCLE_PATH} />
        </ClipPath>
        <ClipPath id={clip2Id}>
          <Path d={EMBLEM_PATH} fillRule="evenodd" clipRule="evenodd" />
        </ClipPath>

        <SvgLinearGradient id={paint0Id} x1="0" y1="0" x2="500" y2="500" gradientUnits="userSpaceOnUse">
          <Stop offset="0.0988" stopColor="#ECD289" />
          <Stop offset="0.7356" stopColor="#A08049" />
        </SvgLinearGradient>

        <SvgRadialGradient
          id={paint1Id}
          cx="50%"
          cy="45%"
          rx="50%"
          ry="50%"
          gradientUnits="userSpaceOnUse"
        >
          <Stop offset="0%" stopColor="#FFFFFF" />
          <Stop offset="25%" stopColor="#FFF2B2" />
          <Stop offset="70%" stopColor="#D8AD2A" />
          <Stop offset="100%" stopColor="#B38612" />
        </SvgRadialGradient>

        <SvgLinearGradient id={paint2Id} x1="0" y1="0" x2="500" y2="500" gradientUnits="userSpaceOnUse">
          <Stop stopColor="#1E180E" />
          <Stop offset="1" stopColor="#F2BA0F" />
        </SvgLinearGradient>
      </Defs>

      {/* Layer 1: Outer Coin Base Rim */}
      <G clipPath={`url(#${clip0Id})`}>
        <G transform="matrix(0.111746 -0.101947 0.101947 0.111746 38.2538 106.281)">
          <Rect x="0" y="0" width="1028.65" height="720.759" fill={`url(#${paint0Id})`} />
          <Rect x="0" y="0" width="1028.65" height="720.759" transform="scale(1 -1)" fill={`url(#${paint0Id})`} />
          <Rect x="0" y="0" width="1028.65" height="720.759" transform="scale(-1 1)" fill={`url(#${paint0Id})`} />
          <Rect x="0" y="0" width="1028.65" height="720.759" transform="scale(-1)" fill={`url(#${paint0Id})`} />
        </G>
      </G>

      {/* Layer 2: Inner Golden Coin Disc with Radial Sheen (Native-safe fallback) */}
      <Circle cx="75.166" cy="75.1885" r="68.028" fill={`url(#${paint1Id})`} />

      {/* Layer 3: Mudra Knot Central Emblem */}
      <G clipPath={`url(#${clip2Id})`}>
        <G transform="matrix(0.0482412 0.00810302 -0.00803365 0.0478282 67.0854 87.4372)">
          <Rect x="0" y="0" width="1906.99" height="2084.94" fill={`url(#${paint2Id})`} />
          <Rect x="0" y="0" width="1906.99" height="2084.94" transform="scale(1 -1)" fill={`url(#${paint2Id})`} />
          <Rect x="0" y="0" width="1906.99" height="2084.94" transform="scale(-1 1)" fill={`url(#${paint2Id})`} />
          <Rect x="0" y="0" width="1906.99" height="2084.94" transform="scale(-1)" fill={`url(#${paint2Id})`} />
        </G>
      </G>
    </Svg>
  );
};

